def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    def dfs(graph, current, path, visited):
        visited.add(current)
        path.append(current)
        if current == goal:
            return path
        for neighbor in graph[current]:
            if neighbor not in visited:
                new_path = dfs(graph, neighbor, path[:], visited)
                if new_path:
                    return new_path
        path.pop()
        visited.remove(current)
        return None

    return dfs(graph, start, [start], set())

