def find_path(graph, start, goal):
    if start == goal:
        # If the start and goal are the same, there is a direct path to the same node
        return [start]

    # Initialize the queue with a tuple (previous node, direct edge)
    queue = [(None, start)]
    # Initialize a dictionary to keep track of the path
    path = {node: None for node in graph}
    # Initialize a set to keep track of visited nodes
    visited = set()

    while queue:
        current_node, previous_edge = queue.pop(0)  # Pop the first element (FIFO)

        # If we've reached the goal, reconstruct the path
        if current_node == goal:
            path[goal] = previous_edge
            reconstruction_path = [goal]
            while path[goal] != None:
                goal = path[goal]
                reconstruction_path.append(goal)
            return reconstruction_path[::-1]  # Reverse the path

        if current_node not in visited:
            visited.add(current_node)
            for neighbor in graph[current_node]:
                if neighbor not in visited:
                    path[neighbor] = current_node
                    queue.append((neighbor, current_node))
    # If the goal is not reachable
    return None
