def find_path(graph, start, goal):
    def heuristic(node):
        # Simple heuristic, just the distance to the goal.
        return (graph[goal].count(node), abs(ord(goal) - ord(node)))

    def a_star_search(graph, start, goal, heuristic):
        # Sort by the heuristic value, then by node name
        frontier = [(0 + heuristic(start), start, [start])]
        explored = set()

        while frontier:
            new_cost, node, path = min(frontier)
            frontier.remove((new_cost, node, path))

            if node == goal:
                return path + [node]

            if node in explored:
                continue

            explored.add(node)

            for neighbor in graph[node]:
                if neighbor not in explored:
                    new_path = path + [neighbor]
                    cost = new_cost + 1
                    priority = cost + heuristic(neighbor)
                    frontier.append((priority, neighbor, new_path))

            frontier.sort()

        return None

    return a_star_search(graph, start, goal, heuristic=heuristic)
