def find_path(graph, start, goal):
    # Create a dictionary to keep track of the previous node in the path for each node
    def reconstruct_path(came_from, current):
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.append(current)
        return path[::-1]

    # Create dictionaries to keep track of visited nodes and the path from start to current node
    visited = set()
    came_from = {start: None}

    # Queue to hold the nodes to be explored
    queue = [start]

    while queue:
        current = queue.pop(0)

        if current == goal:
            return reconstruct_path(came_from, current)

        visited.add(current)

        for neighbor in graph[current]:
            if neighbor not in visited:
                queue.append(neighbor)
                came_from[neighbor] = current

    return None
